import subprocess
def run(args, stdin_bytes):
    p = subprocess.run(["./executable"]+args, input=stdin_bytes, capture_output=True)
    return p

def dot_result(flags):
    p = run(["-f",flags,"a.b","X"], b"a\nb")
    return "ON" if p.stdout==b"X" else ("OFF" if p.stdout==b"a\nb" else f"UNEXPECTED {p.stdout!r}")

def predict_dot(flags):
    # find last occurrence of s/w
    last_s = flags.rfind('s')
    last_w = flags.rfind('w')
    if last_s==-1 and last_w==-1:
        return "OFF"
    return "ON" if last_s > last_w else "OFF"

