import subprocess
def run(args, stdin_bytes):
    p = subprocess.run(["./executable"]+args, input=stdin_bytes, capture_output=True)
    return p

def case_result(flags):
    p = run(["-f",flags,"FOO","bar"], b"FOO foo")
    if p.stdout==b"bar bar":
        return "INS"
    elif p.stdout==b"bar foo":
        return "SENS"
    else:
        return f"UNEXPECTED {p.stdout!r}"

def predict_case(flags):
    # last among c,i,w where w=>SENS
    last_c = flags.rfind('c')
    last_i = flags.rfind('i')
    last_w = flags.rfind('w')
    last = max(last_c, last_i, last_w)
    if last==-1:
        return "SENS"
    if last==last_i:
        return "INS"
    else:
        return "SENS"  # c or w

from itertools import product
alphabet = ["c","e","i","m","s","w","x"]
mismatch=[]
for l in [1,2,3]:
    for tup in product(alphabet, repeat=l):
        f="".join(tup)
        actual=case_result(f)
        pred=predict_case(f)
        if actual!=pred:
            mismatch.append((f,actual,pred))
print(f"case mismatches with w-as-c: {len(mismatch)}")
for f,a,p in mismatch[:20]:
    print(f,a,p)

# Also test longer random
import random
for _ in range(20):
    f="".join(random.choice(alphabet) for _ in range(5))
    actual=case_result(f)
    pred=predict_case(f)
    if actual!=pred:
        print(f"MISMATCH {f!r} {actual} vs {pred}")

