use clap::{Arg, ArgAction, Command};
use std::io::{self, Read, Write};
use std::process;

fn cli() -> Command {
    Command::new("sd")
        .version("1.0.0")
        .about("An intuitive find & replace CLI")
        .arg(
            Arg::new("preview")
                .short('p')
                .long("preview")
                .action(ArgAction::SetTrue)
                .help("Display changes in a human reviewable format (the specifics of the format are likely to change in the future)"),
        )
        .arg(
            Arg::new("fixed-strings")
                .short('F')
                .long("fixed-strings")
                .action(ArgAction::SetTrue)
                .help("Treat FIND and REPLACE_WITH args as literal strings"),
        )
        .arg(
            Arg::new("max-replacements")
                .short('n')
                .long("max-replacements")
                .value_name("LIMIT")
                .default_value("0")
                .value_parser(clap::value_parser!(usize))
                .help("Limit the number of replacements that can occur per file. 0 indicates unlimited replacements"),
        )
        .arg(
            Arg::new("flags")
                .short('f')
                .long("flags")
                .value_name("FLAGS")
                .help("Regex flags. May be combined (like `-f mc`).\n\nc - case-sensitive\n\ne - disable multi-line matching\n\ni - case-insensitive\n\nm - multi-line matching\n\ns - make `.` match newlines\n\nw - match full words only"),
        )
        .arg(
            Arg::new("FIND")
                .help("The regexp or string (if using `-F`) to search for")
                .required(true),
        )
        .arg(
            Arg::new("REPLACE_WITH")
                .help("What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc")
                .required(true),
        )
        .arg(
            Arg::new("FILES")
                .help("The path to file(s). This is optional - sd can also read from STDIN.\n\nNote: sd modifies files in-place by default. See documentation for examples.")
                .num_args(0..),
        )
}

fn is_hex(b: u8) -> bool {
    matches!(b, b'0'..=b'9' | b'a'..=b'f' | b'A'..=b'F')
}

fn hex_val(b: u8) -> u32 {
    match b {
        b'0'..=b'9' => (b - b'0') as u32,
        b'a'..=b'f' => (b - b'a' + 10) as u32,
        b'A'..=b'F' => (b - b'A' + 10) as u32,
        _ => 0,
    }
}

// Unescape replacement string with bug: \xHH and \uHHHH drop next char
fn unescape_replacement(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] != b'\\' {
            // push char (handle utf8)
            // Since s is valid utf8, we can slice char by char
            // Find next char boundary
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        } else {
            // backslash
            if i + 1 >= bytes.len() {
                out.push('\\');
                i += 1;
            } else {
                let nxt = bytes[i+1];
                match nxt {
                    b'n' => { out.push('\n'); i += 2; }
                    b't' => { out.push('\t'); i += 2; }
                    b'r' => { out.push('\r'); i += 2; }
                    b'\'' => { out.push('\''); i += 2; }
                    b'"' => { out.push('"'); i += 2; }
                    b'\\' => { out.push('\\'); i += 2; }
                    b'x' => {
                        // need 2 hex digits
                        if i+3 < bytes.len() && is_hex(bytes[i+2]) && is_hex(bytes[i+3]) {
                            let v = hex_val(bytes[i+2])*16 + hex_val(bytes[i+3]);
                            if let Some(ch) = char::from_u32(v) {
                                out.push(ch);
                                // bug: drop next char (one Unicode scalar) after hex, if any
                                // advance past \xHH (4 bytes: \,x,H,H) -- note: hex digits are ascii, 1 byte each
                                i += 4;
                                // drop next char
                                if i < bytes.len() {
                                    // Need to handle utf8 char length: s[i..] may not be char boundary if we are in middle of original? But i is at byte index in original s, which is char boundary (since we only advanced by ascii + hex ascii). So safe.
                                    // However if remaining starts with multi-byte char, drop whole char
                                    if i < s.len() {
                                        if let Some(ch2) = s[i..].chars().next() {
                                            i += ch2.len_utf8();
                                        } else {
                                            i += 1;
                                        }
                                    } else {
                                        // i beyond s.len()? shouldn't happen since bytes.len()==s.len()
                                    }
                                }
                            } else {
                                // invalid? shouldn't happen for \x (0-FF always valid), but keep literal
                                out.push('\\');
                                out.push('x');
                                i += 2;
                            }
                        } else {
                            out.push('\\');
                            out.push('x');
                            i += 2;
                        }
                    }
                    b'u' => {
                        // need 4 hex digits
                        if i+5 < bytes.len() && is_hex(bytes[i+2]) && is_hex(bytes[i+3]) && is_hex(bytes[i+4]) && is_hex(bytes[i+5]) {
                            let v = hex_val(bytes[i+2])*16*16*16 + hex_val(bytes[i+3])*16*16 + hex_val(bytes[i+4])*16 + hex_val(bytes[i+5]);
                            if let Some(ch) = char::from_u32(v) {
                                out.push(ch);
                                i += 6; // \,u,4 hex
                                if i < bytes.len() {
                                    if i < s.len() {
                                        if let Some(ch2) = s[i..].chars().next() {
                                            i += ch2.len_utf8();
                                        } else {
                                            i += 1;
                                        }
                                    }
                                }
                            } else {
                                // invalid scalar (surrogate etc): keep literal
                                out.push('\\');
                                out.push('u');
                                i += 2;
                            }
                        } else {
                            out.push('\\');
                            out.push('u');
                            i += 2;
                        }
                    }
                    _ => {
                        // unknown escape: keep as is (backslash + char)
                        // Need to push backslash + the char (which may be multi-byte?)
                        out.push('\\');
                        // nxt is single byte, but if next char is multi-byte, bytes[i+1] is first byte, need to push whole char
                        // Since s is utf8, s[i+1..] starts with that char
                        if let Some(ch2) = s[i+1..].chars().next() {
                            out.push(ch2);
                            i += 1 + ch2.len_utf8();
                        } else {
                            out.push(nxt as char);
                            i += 2;
                        }
                    }
                }
            }
        }
    }
    out
}

fn is_word_byte(b: u8) -> bool {
    matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'_')
}
fn is_ascii_letter_underscore(b: u8) -> bool {
    matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'_')
