            // push char (handle utf8)
            // Since s is valid utf8, we can slice char by char
            // Find next char boundary
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        } else {
            // backslash
            if i + 1 >= bytes.len() {
                out.push('\\');
                i += 1;
            } else {
                let nxt = bytes[i+1];
                match nxt {
                    b'n' => { out.push('\n'); i += 2; }
                    b't' => { out.push('\t'); i += 2; }
                    b'r' => { out.push('\r'); i += 2; }
                    b'\'' => { out.push('\''); i += 2; }
                    b'"' => { out.push('"'); i += 2; }
                    b'\\' => { out.push('\\'); i += 2; }
                    b'x' => {
                        // need 2 hex digits
                        if i+3 < bytes.len() && is_hex(bytes[i+2]) && is_hex(bytes[i+3]) {
                            let v = hex_val(bytes[i+2])*16 + hex_val(bytes[i+3]);
                            if let Some(ch) = char::from_u32(v) {
                                out.push(ch);
                                // bug: drop next char (one Unicode scalar) after hex, if any
                                // advance past \xHH (4 bytes: \,x,H,H) -- note: hex digits are ascii, 1 byte each
                                i += 4;
                                // drop next char
                                if i < bytes.len() {
                                    // Need to handle utf8 char length: s[i..] may not be char boundary if we are in middle of original? But i is at byte index in original s, which is char boundary (since we only advanced by ascii + hex ascii). So safe.
                                    // However if remaining starts with multi-byte char, drop whole char
                                    if i < s.len() {
                                        if let Some(ch2) = s[i..].chars().next() {
                                            i += ch2.len_utf8();
                                        } else {
                                            i += 1;
                                        }
                                    } else {
                                        // i beyond s.len()? shouldn't happen since bytes.len()==s.len()
                                    }
                                }
                            } else {
                                // invalid? shouldn't happen for \x (0-FF always valid), but keep literal
                                out.push('\\');
                                out.push('x');
                                i += 2;
                            }
                        } else {
                            out.push('\\');
                            out.push('x');
                            i += 2;
                        }
                    }
                    b'u' => {
                        // need 4 hex digits
                        if i+5 < bytes.len() && is_hex(bytes[i+2]) && is_hex(bytes[i+3]) && is_hex(bytes[i+4]) && is_hex(bytes[i+5]) {
                            let v = hex_val(bytes[i+2])*16*16*16 + hex_val(bytes[i+3])*16*16 + hex_val(bytes[i+4])*16 + hex_val(bytes[i+5]);
                            if let Some(ch) = char::from_u32(v) {
                                out.push(ch);
                                i += 6; // \,u,4 hex
                                if i < bytes.len() {
                                    if i < s.len() {
                                        if let Some(ch2) = s[i..].chars().next() {
                                            i += ch2.len_utf8();
                                        } else {
                                            i += 1;
                                        }
                                    }
                                }
                            } else {
                                // invalid scalar (surrogate etc): keep literal
                                out.push('\\');
                                out.push('u');
                                i += 2;
                            }
                        } else {
                            out.push('\\');
                            out.push('u');
                            i += 2;
                        }
                    }
                    _ => {
                        // unknown escape: keep as is (backslash + char)
                        // Need to push backslash + the char (which may be multi-byte?)
                        out.push('\\');
                        // nxt is single byte, but if next char is multi-byte, bytes[i+1] is first byte, need to push whole char
                        // Since s is utf8, s[i+1..] starts with that char
                        if let Some(ch2) = s[i+1..].chars().next() {
                            out.push(ch2);
                            i += 1 + ch2.len_utf8();
                        } else {
                            out.push(nxt as char);
                            i += 2;
                        }
                    }
                }
            }
        }
    }
    out
}

fn is_word_byte(b: u8) -> bool {
    matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'_')
}
fn is_ascii_letter_underscore(b: u8) -> bool {
    matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'_')
}

// Check ambiguous on original replacement string, return (group, trailing, pos) for first ambiguous?
// On ambiguous, print error and exit.
fn check_ambiguous(repl: &str) {
    let b = repl.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] != b'$' {
            // advance by char
            let ch_len = repl[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            i += ch_len;
            continue;
        }
        // b[i] == '$'
        if i + 1 >= b.len() {
            break; // trailing $, no check
        }
        let nxt = b[i+1];
        if nxt == b'$' {
            i += 2;
            continue;
        }
        if nxt == b'{' {
            // braced, skip until }? Just skip "${" and continue? For ambiguous check, braced never ambiguous, so skip the whole ${...}?
            // Find closing }?
            // Simplest: skip "$" and "{" and continue scanning after? But inside braces may contain $?
            // Actually "${1}" contains no $, so just skip 2 and continue.
            i += 2;
            continue;
        }
        if nxt.is_ascii_digit() {
            // parse digits
            let mut j = i+1;
            while j < b.len() && b[j].is_ascii_digit() {
                j += 1;
            }
            // digits are b[i+1..j]
            if j < b.len() && is_ascii_letter_underscore(b[j]) {
                // ambiguous! Need to find trailing word chars: from j to k where word chars [A-Za-z0-9_]
                let mut k = j;
                while k < b.len() && is_word_byte(b[k]) {
                    k += 1;
                }
                // group is $[digits] = b[i..j]
                let group = &repl[i..j];
                // trailing is b[j..k]
                let trailing = &repl[j..k];
                // hint is ${digits} + trailing? Actually ${...} with digits without $?
                // digits part without $: repl[i+1..j]
                let digits = &repl[i+1..j];
                let hint = format!("${{{}}}{}", digits, trailing);
                // carets: spaces = i+1? Actually off-by-one: carets start at i+1, length = (j-i-1?) Wait group len = j-i (including $), trailing len = k-j, total carets = (j-i-1?) Let's compute: for $1a, i=0, j=2 ($,1), k=3 (a). Carets should be at i+1=1 with len 2 (^^). That's (k - (i+1)) = 2. Good. For $12ab, i=0,j=3,k=5, carets at 1 len 4. Good.
                let num_spaces = i + 1;
                let num_carets = k - (i+1);
                let spaces = " ".repeat(num_spaces);
                let carets = "^".repeat(num_carets);
                eprintln!("error: The numbered capture group `{}` in the replacement text is ambiguous.", group);
                eprintln!("hint: Use curly braces to disambiguate it `{}`.", hint);
                eprintln!("{}", repl);
                eprintln!("{}{}", spaces, carets);
                process::exit(1);
            } else {
                // not ambiguous, continue after digits
                i = j;
                continue;
            }
        } else {
            // $ + non-digit, non-$ , non-{ : could be named group ($a, $_) or other ($-, $space). No ambiguous check, just advance past $?
            // For named, skip? Just move past $ by 1 char?
            // To correctly handle $$ already handled, ${ already, digits already. For others, just i+=1 and continue? But need to handle multi-byte after $?
            // Simplest: advance by 1 (the $) and continue; next iteration will handle next char normally.
            // However for "$a" (named), we should not treat "a" as start of new check, but that's fine.
            i += 1;
            continue;
        }
    }
}

fn main() {
    let matches = cli().get_matches();

    let preview = matches.get_flag("preview");
    let fixed = matches.get_flag("fixed-strings");
    let limit = *matches.get_one::<usize>("max-replacements").unwrap();
    let flags_str = matches.get_one::<String>("flags").map(|s| s.as_str()).unwrap_or("");
    let find = matches.get_one::<String>("FIND").unwrap().clone();
    let replace_raw = matches.get_one::<String>("REPLACE_WITH").unwrap().clone();
    let files: Vec<String> = matches.get_many::<String>("FILES").map(|v| v.cloned().collect()).unwrap_or_default();

    // flags handling
    // case: last among c,i,w
    let mut last_case: Option<char> = None;
    for c in flags_str.chars() {
        if c == 'c' || c == 'i' || c == 'w' {
            last_case = Some(c);
        }
    }
    let case_insensitive = matches!(last_case, Some('i'));

    // dot: last among s,w
    let mut last_dot: Option<char> = None;
    for c in flags_str.chars() {
        if c == 's' || c == 'w' {
            last_dot = Some(c);
        }
    }
    let dot_matches = matches!(last_dot, Some('s'));

    // multiline: !e && !w && (m || !s)
    let has_e = flags_str.contains('e');
    let has_w = flags_str.contains('w');
    let has_m = flags_str.contains('m');
    let has_s = flags_str.contains('s');
    let multi_line = !has_e && !has_w && (has_m || !has_s);

    let word = has_w;

    // pattern
    let mut pattern = if fixed {
        regex::escape(&find)
    } else {
        find.clone()
    };
    if word {
        pattern = format!(r"\b{}\b", pattern);
    }

    // build regex (bytes)
    let mut builder = regex::bytes::RegexBuilder::new(&pattern);
    builder.case_insensitive(case_insensitive);
    builder.multi_line(multi_line);
    builder.dot_matches_new_line(dot_matches);
    let re = match builder.build() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: invalid regex {}", e);
            process::exit(1);
        }
    };

    // replacement handling
    // For fixed: literal, no check, no unescape
    // For regex: check ambiguous on original, then unescape, then expand
    let replace_unescaped: String;
    let is_literal: bool;
    if fixed {
        is_literal = true;
        replace_unescaped = replace_raw.clone(); // not used for expansion, use NoExpand
    } else {
        check_ambiguous(&replace_raw);
        replace_unescaped = unescape_replacement(&replace_raw);
        is_literal = false;
    }

    // helper to apply replacement to bytes
    let apply = |input: &[u8]| -> Vec<u8> {
        if is_literal {
            if limit == 0 {
                re.replace_all(input, regex::bytes::NoExpand(replace_raw.as_bytes())).into_owned()
            } else {
                re.replacen(input, limit, regex::bytes::NoExpand(replace_raw.as_bytes())).into_owned()
            }
        } else {
            if limit == 0 {
                re.replace_all(input, replace_unescaped.as_str()).into_owned()
            } else {
                re.replacen(input, limit, replace_unescaped.as_str()).into_owned()
            }
        }
    };

    if files.is_empty() {
        // stdin
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).unwrap_or(0);
        let out = apply(&buf);
        let mut stdout = io::stdout();
        stdout.write_all(&out).unwrap_or(());
    } else {
        // files: first read all
        let mut contents: Vec<(String, Vec<u8>)> = Vec::new();
        for path in &files {
            // Special handling for "-" ? Original gives invalid path for "-"
            // fs::read("-") would give NotFound (since file "-" doesn't exist in cwd? Actually if cwd has file "-", it would succeed, but original gives invalid path even if file "-" exists? Let's test: we created file "-" in tmpdir and it succeeded via absolute path, but what about relative "-"?
            // For path == "-", always invalid path (even if file exists? Need to test: create file named "-" in cwd and run sd with "-" as arg)
            // For now, if path == "-", directly error invalid path
            if path == "-" {
                eprintln!("error: invalid path: {}", path);
                process::exit(1);
            }
            match std::fs::read(path) {
                Ok(data) => contents.push((path.clone(), data)),
                Err(e) => {
                    if e.kind() == io::ErrorKind::NotFound {
                        eprintln!("error: invalid path: {}", path);
                    } else {
                        eprintln!("error: {}", e);
                    }
                    process::exit(1);
                }
            }
        }
        // apply to each
        let mut results: Vec<(String, Vec<u8>)> = Vec::new();
        for (path, data) in contents {
            let out = apply(&data);
            results.push((path, out));
        }
        if preview {
            if results.len() == 1 {
                let mut stdout = io::stdout();
                stdout.write_all(&results[0].1).unwrap_or(());
            } else {
                let mut stdout = io::stdout();
                for (path, out) in &results {
                    let header = format!("----- FILE {} -----\n", path);
                    stdout.write_all(header.as_bytes()).unwrap_or(());
                    stdout.write_all(out).unwrap_or(());
                }
            }
        } else {
            for (path, out) in &results {
                // write back (preserve? just write)
                if let Err(e) = std::fs::write(path, out) {
                    eprintln!("error: {}", e);
                    process::exit(1);
                }
            }
        }
    }
}
RS
"}

